// lib/area-stats.ts is generated by scripts/area-stats.py from ONS and MHCLG tables. These checks
// catch a bad regeneration (a missing borough, a broken parse) before it reaches an area page.
const test = require('node:test')
const assert = require('node:assert/strict')
const { areaStats } = require('../lib/area-stats.ts')
const { boroughMeta } = require('../lib/boroughs.ts')
const { bandFor } = require('../lib/area-stats-types.ts')

const inRange = (v, lo, hi) => v === null || (typeof v === 'number' && v >= lo && v <= hi)

test('every London local authority has stats, and every borough page maps to one', () => {
  const slugs = Object.keys(areaStats.boroughs)
  assert.equal(slugs.length, 33)
  for (const slug of slugs) assert.ok(boroughMeta[slug], `${slug} has no area page`)
  for (const [slug, meta] of Object.entries(boroughMeta)) {
    if (meta.kind !== 'neighbourhood') assert.ok(areaStats.boroughs[slug], `${slug} has no stats`)
  }
})

test('scores and shares are in range', () => {
  for (const b of Object.values(areaStats.boroughs)) {
    for (const v of [b.median, b.medianExisting, b.medianNew, ...Object.values(b.medianByAge), ...Object.values(b.medianByType)]) assert.ok(inRange(v, 1, 120), `${b.name}: ${v}`)
    for (const v of [b.pctCPlus, b.pctCPlusExisting, b.pctCPlusNew, ...Object.values(b.pctCPlusByType)]) assert.ok(inRange(v, 0, 100), `${b.name}: ${v}`)
    const banded = Object.values(b.lodgements.bands).reduce((a, n) => a + n, 0)
    assert.ok(banded <= b.lodgements.total && banded >= b.lodgements.total * 0.99, `${b.name}: bands ${banded} vs total ${b.lodgements.total}`)
  }
})

test('Stratford is six Newham neighbourhoods, not a council', () => {
  assert.equal(areaStats.boroughs.stratford, undefined)
  assert.equal(areaStats.stratford.length, 6)
  for (const n of areaStats.stratford) {
    assert.match(n.onsName, /^Newham \d{3}$/)
    assert.ok(inRange(n.median, 1, 120) && inRange(n.pctCPlus, 0, 100), n.name)
  }
})

test('every figure carries a dated source', () => {
  for (const key of ['ons', 'mhclg', 'msoaNames']) assert.ok(areaStats.sources[key].url.startsWith('https://'), key)
  assert.match(areaStats.sources.ons.published, /^\d{4}-\d{2}-\d{2}$/)
  assert.match(areaStats.sources.mhclg.published, /^\d{4}-\d{2}-\d{2}$/)
  assert.match(areaStats.sources.mhclg.period, /^[A-Z][a-z]+ \d{4} to [A-Z][a-z]+ \d{4}$/)
})

test('band thresholds match the RdSAP scale', () => {
  for (const [score, band] of [[92, 'A'], [91, 'B'], [81, 'B'], [80, 'C'], [69, 'C'], [68, 'D'], [55, 'D'], [54, 'E'], [39, 'E'], [38, 'F'], [21, 'F'], [20, 'G'], [1, 'G']]) {
    assert.equal(bandFor(score), band, `${score}`)
  }
})
